# -*- coding: utf-8 -*-
"""Лише нові розділи 63–66 + перецілений тест руки 2 з §41.
Повна регресія в цьому середовищі не доходить (§54 на каталог_повний з'їдає
пам'ять і процес гине без рядка). Це НЕ заміна регресії — це вимір нового."""
import sys, os as _os, json as _json, tempfile as _tf, re as _re
_тут = _os.path.dirname(_os.path.abspath(__file__))
_шлях = lambda і: і if _os.path.exists(і) else _os.path.join(_тут, і)
import feed as _Ф0
import bridge as _BR32, brief as _Б64, каблук as _КБ63, pipeline as _PL56, feed as _Ф, outfit as O
ok, збої, пропущено = 0, [], []
def тест(назва, умова, деталь="", без_входу=False):
    """`без_входу=True` — тест не виконувався, бо нема ВХОДУ (фікстури, каталогу).
    Це не провал і не успіх: рахується окремо, і підсумок каже це вголос."""
    global ok
    if без_входу: пропущено.append(назва); print(f"  ~ {назва}  [БЕЗ ВХОДУ: {деталь}]"); return
    if умова: ok += 1; print(f"  ✓ {назва}")
    else: збої.append(назва); print(f"  ✗ {назва}  {деталь}")


def main():
    # ── ФІКСТУРИ `каталог_brief.xml` НЕ ІСНУЄ (08.09.2026, крок аудиту A7) ───────
    # ЩО ЗМІРЯНО: `git ls-files` не знає цього файла — його НЕ ВИДАЛЯЛИ, його ніколи
    # не комітили. Отже пʼять тестів нижче, які його читають, ЧЕРВОНІ від дня
    # написання на будь-якій машині, крім авторської, і їхня червоність не несе
    # інформації. Постійно червоний гейт навчає читача не дивитись на червоне — це
    # гірше за відсутній тест.
    # ЩО СТАЛО: фікстура — це «малий справжній фід», і роль її виконує будь-який
    # каталог, що лежить на диску (`feed.каталог_на_диску`). Коли нема жодного,
    # тести не ПАДАЮТЬ, а пропускаються з міткою «без входу»: різниця між «не
    # виконано» і «виконано й провалено» — та сама, яку система вимагає від власних
    # правил.
    # ФІКСТУРУ ВІДНОВЛЕНО 08.09.2026 — стратифікованою вибіркою з каталогу, що
    # лежить на диску: 427 оферів, по 40 на слот (менше там, де в каталозі менше),
    # по черзі між магазинами. Це «малий справжній фід» — рівно те, чим фікстура й
    # була, і чого не можна вигадати руками: тести нижче читають реальні назви,
    # параметри й фото. Побудова детермінована (сід 17), тож прогін відтворюваний.
    try:
        _БРИФ = _Ф0.каталог_на_диску("каталог_brief.xml")
        _БРИФ_Є = True
    except SystemExit:
        _БРИФ, _БРИФ_Є = "каталог_brief.xml", False
    _вх32 = dict(шкіра="#deb295", волосся="#f1dbaa", очі="#759087", зріст=167,
                 обхвати={"плечі": 98, "груди": 90, "талія": 72, "стегна": 100, "коліно": 37, "литка": 35},
                 випадок="робота, офіс, 11:00, 18 °C",
                 сценарій=dict(нагода="робота", місце="офіс", година=11, темп_c=18.0),
                 вимоги="", гілка=0)

    print("41-перецілено. ДОНОР — ПОЛОМКА, А НЕ ТЛО")
    _фд41, _кш41 = _tf.mkstemp(suffix=".json"); _os.close(_фд41); _json.dump({}, open(_кш41, "w"))
    _вх41 = dict(_вх32, каталог=_шлях(_БРИФ), кеш_кольорів=_кш41, вимоги="хочу тонкі підбори",
                 намір="fashion_forward", сід=5, варіантів=10, бюджет_символів=120000)
    _р41 = _json.loads(_BR32.виклик("запити", _json.dumps(_вх41, ensure_ascii=False))); _os.remove(_кш41)
    _дон41 = "донор" in (_р41.get("поломки_руки_2") or [])
    # ── ПУЛ ПІД СМІЛИВИМ НАМІРОМ (V02, наряд Н-V02-004) ─────────────────────────
    # ЩО ЦЕ ЛОВИТЬ. §41 вище ганяє fashion_forward × каталог_brief і був зелений
    # при `пул_речей=0`: він дивиться на `поломки_руки_2` і плацебо, а `пул_чому`
    # не читає. Тим часом `_комбінації_вибіркою` годувала суд комбінаціями, де та
    # сама двослотова річ (комплект → верх/низ, кардиган → верхній_шар) стояла
    # двічі, і `outfit.перевірити_вхід` законно валила образ ValueError-ом —
    # сміливий намір на фікстурі артефакта не збирав пул ЖОДНОГО разу.
    тест("сміливий намір на фікстурі артефакта збирає пул (V02)",
         not _р41.get("пул_чому") and (_р41.get("пул_речей") or 0) > 0,
         _р41.get("пул_чому"))
    _ід41 = lambda к: {r["id"] for пул in (к or {}).values() for r in пул}
    # ── ПУЛ — ПЕРЕДУМОВА ЦЬОГО ВИМІРУ, А НЕ ТЛО (V02, наряд Н-00-02) ────────────
    # ЩО ТУТ БУЛО ЗЛАМАНО. Тест ганяє `fashion_forward` × `каталог_brief.xml` — рівно
    # той вхід, на якому `composer.зібрати` кидає `ValueError: однакові id речей`,
    # `bridge._пакет_каталогу` ловить його загальним `except` і віддає `готово=False`.
    # Тоді `кандидати` і `кандидати_донора` порожні ОБИДВА, `_ід41` дає двічі порожню
    # множину, а перша умова починається з `not _дон41` — і все речення виконується
    # ТРИВІАЛЬНО. Виміряно 10.09.2026: `пул_речей=0`, `пул_чому="ValueError: однакові
    # id речей ['ж-05525@gepur.com']"`, і при цьому «ПРОЙДЕНО 53, ВПАЛО 0». Тобто
    # єдиний гейт, який ходив цим шляхом, 53 прогони поспіль звітував зелено над
    # найдорожчою поломкою продукту.
    # ЩО СТАЛО. Без пулу фраза «рука 2 про ТУ САМУ людину» не має предмета, тож умова
    # пулу стоїть ПЕРШОЮ, а `пул_чому` — в деталі: червоне мусить називати причину, а
    # не лише факт. Закриє це не цей файл, а наряд Н-V02-004 (`composer`).
    _пул41 = bool(_р41.get("пул_речей")) and not _р41.get("пул_чому")
    тест("донор — одна з випадкових поломок, а не тло: коли він випав, кандидати руки 2 інші; "
         "коли не випав, рука 2 про ТУ САМУ людину, і плацебо чесно каже, що міряти нема чого "
         "(і пул зібрано — на порожньому пулі порівнювати нема чого)",
         # 04.09 (пізніше того ж дня): пул тепер залежить і від СЦЕНИ (відсів за формальністю,
         # composer._поза_сценою) і від ГІЛКИ — тож поломки «доречність» і «палітра» законно
         # дають руці 2 інший пул без донора. Вимога: донор → пул інший; плацебо чесне завжди.
         _пул41
         and (not _дон41 or _ід41(_р41.get("кандидати")) != _ід41(_р41.get("кандидати_донора")))
         and (_р41["мета"]["плацебо"]["придатне"] is not None) == _дон41
         and _р41["мета"]["плацебо"]["донор"] == _дон41,
         ("пул_речей=%s" % _р41.get("пул_речей"), "пул_чому=%s" % _р41.get("пул_чому"),
          _р41.get("поломки_руки_2"), _р41["мета"]["плацебо"].get("придатне")))

    print("63. КАБЛУК: ПРОХАННЯ ПРО ВЗУТТЯ СТАЄ ВІДБОРОМ, А НЕ РЕЧЕННЯМ У ПРОМПТІ (04.09.2026)")
    # ЩО ЦЕ ЛОВИТЬ. Тестувальниця двічі просила тонкі підбори й двічі діставала
    # взуття не на них. Розтин показав три різні дефекти, і кожен із них лишався
    # невидимим для попередніх гейтів: §41 перевіряв, що ТЕКСТ прохання присутній у
    # чотирьох промптах, — тобто покриття, а не ефект. Тут перевіряється ефект:
    # чи змінився ПУЛ, чи змінився РЯДОК КОДУ, чи названо невідоме невідомим.
    import каблук as _КБ63

    # 1. клас речі з тексту каталогу
    тест("балетка — «каблука нема» ВИЗНАЧЕННЯМ, не статистикою; човник — «каблук є»; "
         "«Kitten Heels» — тонкий; невідоме лишається None, а не тихим дефолтом",
         _КБ63.каблук("Балетки Tay блакитний замш")["є"] is False
         and _КБ63.каблук("Балетки Tay блакитний замш")["джерело"] == "визначення"
         and _КБ63.каблук("Човники з анатомічним мисом Fiona Black")["є"] is True
         and _КБ63.каблук("Босоніжки Kitten Heels чорні CELESTIAL")["форма"] == "тонкий"
         and _КБ63.каблук("Мюлі VS000087828")["є"] is None,
         [_КБ63.каблук(н) for н in ("Балетки Tay", "Човники Fiona", "Мюлі VS000087828")])

    # 2. ПАСТКА ПІДРЯДКА — спіймана виміром, не читанням: «китн» лежить усередині
    #    «бла-КИТН-і», і дев'ять блакитних кедів, кросівок та балеток діставали клас
    #    «тонкий каблук». Мутант: поверни підрядок без межі слова — гейт червоніє.
    тест("«блакитні» не читається як kitten: блакитні кеди, кросівки й балетки лишаються без каблука",
         all(_КБ63.каблук(н)["форма"] is None and _КБ63.каблук(н)["є"] is False
             for н in ("Кеди блакитні з квітами BLOOM BLOOM 08",
                       "Балетки блакитні FLOWER FLOW 08",
                       "Жіночі блакитні кросівки UA W Aurora 3")),
         [_КБ63.каблук(н) for н in ("Кеди блакитні", "Балетки блакитні")])

    # 3. розбір прохання людини
    тест("прохання розбирається з її слів: «тонкі підбори»/«шпилька» → тонкий; «без каблука»/«кросівки» → нема; "
         "порожньо → None (мовчання ≠ прохання)",
         _КБ63.прохання("взуття на тонких підборах") == "тонкий"
         and _КБ63.прохання("хочу шпильки") == "тонкий"
         and _КБ63.прохання("тільки плоска підошва") == "нема"
         and _КБ63.прохання("") is None and _КБ63.прохання("хочу зелену сукню") is None)

    # 4. відсів: суперечить ВИЗНАЧЕННЮ — геть; не оголошено — лишається
    _реч63 = [dict(id="a", каблук_є=False), dict(id="b", каблук_є=None), dict(id="c", каблук_є=True)]
    _л63, _г63, _ч63 = _КБ63.відсів(_реч63, "тонкий")
    тест("відсів під «тонкий»: речі БЕЗ каблука зняті, речі з невідомим каблуком ЛИШИЛИСЬ "
         "(«магазин не сказав» ≠ «не підходить»), і число невідомих названо в сліді",
         [r["id"] for r in _л63] == ["b", "c"] and [r["id"] for r in _г63] == ["a"]
         and "1 без оголошеного каблука" in _ч63, _ч63)
    тест("відсів без прохання нічого не чіпає — фільтр не має права працювати на мовчанні",
         len(_КБ63.відсів(_реч63, None)[0]) == 3)

    # 5. НАСКРІЗЬ ЧЕРЕЗ МІСТ: пул під проханням МЕНШИЙ і не містить жодної речі без каблука
    _фд63, _кш63 = _tf.mkstemp(suffix=".json"); _os.close(_фд63); _json.dump({}, open(_кш63, "w"))
    _вх63 = dict(_вх32, каталог=_шлях(_БРИФ), кеш_кольорів=_кш63, гілка=0, варіантів=10,
                 бюджет_символів=120000, сід=424242)
    _без63 = _json.loads(_BR32.виклик("запити", _json.dumps(dict(_вх63, вимоги=""), ensure_ascii=False)))
    _зв63 = _json.loads(_BR32.виклик("запити", _json.dumps(dict(_вх63, вимоги="взуття на тонких підборах"),
                                                           ensure_ascii=False)))
    _os.remove(_кш63)
    _п_без = (_без63.get("кандидати") or {}).get("взуття") or []
    _п_зв = (_зв63.get("кандидати") or {}).get("взуття") or []
    тест("прохання РІЖЕ пул взуття наскрізь через `bridge.виклик` (не через власний скрипт): "
         "з проханням речей менше, і жодна з них не має класу «без каблука»",
         len(_п_зв) < len(_п_без)
         and not any((r.get("каблук") or "") == "без каблука" for r in _п_зв)
         and any((r.get("каблук") or "") == "без каблука" for r in _п_без),
         "без вимоги %d → з вимогою %d" % (len(_п_без), len(_п_зв)))
    тест("МОВЧАННЯ НАЗВАНЕ: група взуття в промпті несе «каблук не оголошений», а не порожній рядок — "
         "саме в цю прогалину модель вписувала «округлі скульптурні підбори», атрибут, якого в каталозі нема",
         "каблук не оголошений" in _зв63["руки"]["1"])
    тест("вимоги стоять у ключі кеша пакета: два прогони з різними вимогами дають РІЗНІ пули, "
         "а не один із кеша (без цього відсів невидимий на другому виклику)",
         {r["id"] for r in _п_зв} != {r["id"] for r in _п_без})


    print("64. ВИМОГИ ЛЮДИНИ ДОХОДЯТЬ ДО БРИФА Й МІНЯЮТЬ ЙОГО РЯДОК (04.09.2026)")
    # ЩО ЦЕ ЛОВИТЬ. `brief.послаблення` і таблиця `КОНФЛІКТИ` були написані САМЕ
    # після цього провалу («спіймано двічі поспіль»), мали регекс і докстрінг — і не
    # спрацьовували жодного разу: усі три виклики `Б.бриф` у `bridge.запити` йшли
    # без `вимоги=`. Правило, яке виконується, лишає слід і не міняє жодного
    # рішення, — третій ярус. Гейта на нього не було взагалі (grep: 0 збігів).
    import brief as _Б64
    _рм64 = lambda r: next((p["рядок"] for p in (r.get("правила_рук") or {}).get("B", [])
                            if p["код"] == "взуття"), "")
    _F64, _T64, _зр64, _kw64 = _BR32._збірка(_вх63)
    _п64 = _BR32._пакет(_F64, _T64, _зр64, _kw64, _BR32._якір(_вх63), "conventional",
                        _BR32._самозвіт(_вх63), None)
    _ряд = lambda б: [p["рядок"] for p in б["правила"] if p["код"] == "взуття"]
    _б_без = _Б64.бриф(_п64, None, 0, вимоги="")
    _б_зв = _Б64.бриф(_п64, None, 0, вимоги="взуття на тонких підборах")
    тест("рядок брифа про взуття РІЗНИЙ з проханням і без: без прохання код прямо забороняє тонкий каблук, "
         "з проханням — підпорядковує правило людині (before/after, правило 3)",
         _ряд(_б_без) and _ряд(_б_зв) and _ряд(_б_без)[0] != _ряд(_б_зв)[0]
         and "тонкий каблук під широку штанину — ні" in _ряд(_б_без)[0]
         and "вимозі людини" in _ряд(_б_зв)[0], (_ряд(_б_без)[:1], _ряд(_б_зв)[:1]))
    тест("проводка МОСТА, не лише механізм: рядок про взуття в `правила_рук[\"B\"]` приходить із `bridge.виклик` "
         "різним — без прохання код прямо забороняє тонкий каблук, з проханням підпорядковує правило людині. "
         "Тест вище кличе `brief.бриф` напряму й тому НЕ ловить те, що було зламане: три виклики брифа в мості "
         "йшли без `вимоги=`, і механізм послаблення не спрацьовував жодного разу",
         _рм64(_без63) and _рм64(_зв63) and _рм64(_без63) != _рм64(_зв63)
         and "тонкий каблук під широку штанину — ні" in _рм64(_без63)
         and "вимозі людини" in _рм64(_зв63), (_рм64(_без63)[:60], _рм64(_зв63)[:60]))
    тест("блок «ВИМОГИ ЛЮДИНИ — виконати обов'язково» стоїть у руках із кодом і відсутній, коли вимог нема",
         "ВИМОГИ ЛЮДИНИ" in _зв63["руки"]["1"] and "ВИМОГИ ЛЮДИНИ" in _зв63["руки"]["2"]
         and "ВИМОГИ ЛЮДИНИ" not in _без63["руки"]["1"])
    _ПОК64 = open(_шлях("показ.html"), encoding="utf-8").read()
    _код64 = _re.sub(r"/\*.*?\*/", "", _ПОК64, flags=_re.S)   # гейт не має права читати
                                                              # коментар про код як код

    тест("показ шле її слова в канал ВИМОГ, а не лише в опис сцени: `вимоги: ''` константою більше нема; "
         "і нагода не витісняється словами з рядка випадку (руки 3/4, крім випадку, не мають нічого)",
         "вимоги: ''" not in _код64 and "вимоги: слова" in _код64
         and "слова || людяно(с.нагода)" not in _код64
         and "(с.нагода ? людяно(с.нагода) : слова)" in _код64)


    print("65. РУКА 2 ЛАМАЄТЬСЯ ВИПАДКОВО, А НЕ ЗА СТАЛИМ НАБОРОМ (04.09.2026)")
    # ЩО ЦЕ ЛОВИТЬ. Донор, вивернуте ремесло й зіпсований сценарій стояли ЗАВЖДИ:
    # три з п'яти дефектів були сталі, тож «зламана рука» означала завжди один і
    # той самий набір, і питання «яка саме поломка змінює вердикт» відповіді не
    # мало — поломки не роз'єднувались. Та сама хвороба, що її вже лікує абляція
