    print("86. ЗАПАСНИЙ РЯДОК НЕ ЗМАГАЄТЬСЯ НАРІВНІ З ОСНОВНИМ: ДВІ ХВИЛІ ЗА ПОЛЕМ `спроба` (Н-palette-2-098)")
    # Якірний нейтральний рядок додали, щоб слот «взуття»/«сумка» не лишався порожнім
