    _лише_зап73 = _Ф.покриття(_зап73, _к71)
    тест("коли основної хвилі НЕМА, запасний рядок працює як раніше — правило про пріоритет, "
         "не про заборону",
         any(not r["порожньо"] and r["sku"] > 0 for r in _лише_зап73),
         [(r["слот"], r["sku"]) for r in _лише_зап73][:4])

    _вікна73 = [dict(слот="взуття", L_min=0.0, L_max=100.0, C_min=0.0, C_max=24.0,
                     h_from=None, h_to=None, нейтраль=True, спроба=1),
                dict(слот="взуття", L_min=40.0, L_max=70.0, C_min=14.0, C_max=60.0,
                     h_from=100.0, h_to=160.0, нейтраль=False, спроба=0)]
    _речі73 = [dict(id="чорний", слот="взуття", lab=[10.0, 0.5, 0.5], назва="Черевики чорні"),
               dict(id="зелений", слот="взуття", lab=[55.0, -25.0, 15.0], назва="Човники зелені")]
    _к_гілки73 = _КМ73._кандидати_гілки(_речі73, _вікна73, "взуття", set(), "проба", 5)
    _к_гілки_без73 = _КМ73._кандидати_гілки(_речі73[:1], _вікна73, "взуття", set(), "проба", 5)
