    print("87. ЯРЛИК ТІЛА БЕЗ ЦІЛЬОВИХ ЛІТЕР ГАСИВ УВЕСЬ ПРОСТІР КРОЇВ (Н-P08)")
    # Діра: `fit.зони` віддає п'ять ярликів, а `silhouette.ЦІЛЬ_ЛІТЕРИ` знала чотири.
    # Для тіла з ярликом «H/X межа» ціль виходила порожня -> `влучання` 0 на КОЖНІЙ
    # комбінації -> бал 0 -> `простір` порожній -> бриф без силуетного блоку. Причина
