    # bash не дозволяє кириличних імен змінних — це не присвоєння, а спроба виконати
    # команду: код 127, а під `set -e` крок падає. Сам файл про цю пастку знає й
    # пише про неї в коментарі до `LYUSTERKO_CATALOG` — урок застосували до `env:`
    # і не застосували до ключа job'а й до змінної оболонки.
    import ast as _ast89, re as _re89
    _тека89 = _os.path.join(_os.path.dirname(_тут), ".github", "workflows")
