    _ямли89 = sorted(f for f in (_os.listdir(_тека89) if _є89 else []) if f.endswith((".yml", ".yaml")))
    _ід89 = _re89.compile(r"^[A-Za-z_][A-Za-z0-9_-]{0,99}$")

    def _ключі_job89(текст):
        """Ключі jobs: без yaml — на відступах. Рівно два рівні, які тут і є."""
        рядки, у_jobs, ключі = текст.split("\n"), False, []
        for р in рядки:
            if _re89.match(r"^jobs:\s*$", р): у_jobs = True; continue
            if у_jobs and р and not р[0].isspace(): у_jobs = False
            if у_jobs:
                м = _re89.match(r"^  ([^\s#][^:]*):\s*$", р)
                if м: ключі.append(м.group(1))
        return ключі

