    for ф in _ямли89:
        т = open(_os.path.join(_тека89, ф), encoding="utf-8").read()
        _погані_ід89 += [(ф, k) for k in _ключі_job89(т) if not _ід89.match(k)]
        # присвоєння не-ASCII імені на початку рядка в блоці `run:`
        _погані_зм89 += [(ф, м.group(1)) for м in
                         _re89.finditer(r"^\s*([^\s=#]*[^\x00-\x7F][^\s=#]*)=", т, _re89.M)]

