    print("117. ПРИЛАД ПРИ ІМПОРТІ НІЧОГО НЕ ВИКОНУЄ (Н-00-07)")
    # ЩО ЛОВИТЬ. Три прилади тримали всю роботу в тілі модуля: `import траса_петлі`
    # заводив теку `траса/` і йшов у міст, `import measure_person_axis` розпаковував
    # каталог і рахував Жаккари на тисячах SKU, `import гейти_нові` прогонював УСЮ
    # батарею. Ціна не теоретична: модуль, чий імпорт коштує хвилин і лишає по собі
    # файли, не можна прочитати приладом — `відбиток`, `audit_contracts`,
    # `досяжність` саме ІМПОРТУЮТЬ модулі, щоб їх обійти, — і не можна покликати з
    # нього одну функцію: тільки запустити цілком.
    # ЧОМУ САМЕ ТАК МІРЯЄМО. Наявність рядка `if __name__ == "__main__"` — не доказ:
    # його легко дописати НАД тілом, яке вже виконалось при імпорті. Тому міряється
    # спостережне — час імпорту в ОКРЕМОМУ процесі і те, що по собі лишив. Робоча
    # тека процесу навмисно ПОРОЖНЯ і чужа: усе, що прилад пише «поруч із собою»,
