    _діє128, _дет128 = _SP128._аксесуарні_виміри_не_збираються()
    тест("запис ВІДКРИТИЙ і каже це виміром, а не словом: профіль без аргументу "
         "`аксесуарні` не несе жодного з шести вимірів",
         _діє128 and len(_F128.тіло(164, dict(плечі=96, груди=92, талія=76, стегна=98))
                         ["бракує_аксесуарних"]) == len(_F128.АКСЕСУАРНІ_ВИМІРИ),
         _дет128)
    _сир128 = _SP128._поля_без_постачальника()[1]
    тест("перевірка сиріт бачить поля АКСЕСУАРНОЇ гілки: `обхват_голови_см`, `lug_мм`, "
         "`bl`, `ремінь_см`, `край_руки_см` більше не ховаються за тим, що їх не читає "
         "`outfit.елементи`",
         all(п in _сир128 for п in ("обхват_голови_см", "lug_мм", "bl",
                                    "ремінь_см", "край_руки_см")),
         _сир128)
    тест("три старі сироти нікуди не поділись: список ВИРІС, а не переїхав",
         all(п in _сир128 for п in ("відкрита_зона", "полірування", "формальність")),
         _сир128)
    # Джерело споживачів — самі таблиці, не список імен у перевірці: інакше наступне
    # поле аксесуарної гілки випало б з обліку так само мовчки, як ці п'ять.
    тест("споживачі беруться з ТАБЛИЦЬ `АКСЕСУАР_ВИМІР`/`НОСІЇ_КРАЮ`, а не з руками "
         "переписаного списку імен у самій перевірці",
         all('%s.values()' % т in _re.sub(r"#[^\n]*", "", __import__("inspect").getsource(
             _SP128._поля_без_постачальника))
             for т in ("accessory.АКСЕСУАР_ВИМІР", "accessory.НОСІЇ_КРАЮ")),
         None)
    _пр128 = [з["правило"] for з in _A128.без_входу()]
    тест("`без_входу()` називає поіменно те, чого анкетою не лікувати: K-EYE-01, "
         "K-WCH-01, K-GLV-01 (слота нема у фіді), K-HAT-01 (річ є, числа нема), "
         "K-ACC-04 (поле без постачальника) — приймальний рядок наряду",
         all(і in _пр128 for і in ("K-EYE-01", "K-WCH-01", "K-GLV-01",
                                   "K-HAT-01", "K-ACC-04")),
         _пр128)
    тест("кожен новий запис РОЗРІЗНЯЄ брак речі й брак виміру просто в тексті блокера "
         "— інакше читач знову не побачить, що анкета тут не допоможе",
         all(any(с in _A128.БЕЗ_ВХОДУ[і]["блокер"].lower()
                 for с in ("слот", "каталоз", "каталогу", "постачальник"))
             for і in ("K-EYE-01", "K-WCH-01", "K-GLV-01", "K-HAT-01", "K-ACC-04")),
         {і: _A128.БЕЗ_ВХОДУ[і]["блокер"][:40]
          for і in ("K-EYE-01", "K-WCH-01", "K-GLV-01", "K-HAT-01", "K-ACC-04")})
    тест("усі вони лишаються ПИТАННЯМИ з вагою 0: черга на вхід не судить і не "
         "відкидає (K-IO-04)",
         all(з.get("сила") == "питання" and з.get("сила_нп") == 0.0
             and not з.get("блокує") for з in _A128.без_входу()),
         [(з["правило"], з.get("сила"), з.get("сила_нп")) for з in _A128.без_входу()])

    print("129. ПЛОЩА З ГЕОМЕТРІЇ ЗАКРИВАЄ ВХІД ПʼЯТИ КОЛІРНИМ ПРАВИЛАМ (Н-outfit-1-081)")
    # ЩО ЦЕ ЛОВИТЬ. `площі_є` у `outfit.review` вимагає НАЗВАНОГО походження площі, а
    # ставити `джерело_площі` не вмів ніхто: `composer._у_річ` навмисно його не ставить
    # (і це правильно — вигадана площа гірша за мовчання), інших виробників не було.
    # Отже K-COL-01/02/05/06 і K-COMP-03 були недосяжні СТРУКТУРНО: профайлер на
    # `стенд_знімок.дим()` не бачив жодного виклику `перевірка_value`, `бюджет_хроми`,
    # `сім_ї_образу`, `відлуння`. Вхід закрито з боку ВИМІРУ: коли краї речей виміряні,
    # площа рахується з геометрії тіла; коли ні — нічого не ставиться, утримання
    # лишається, і його покриття тепер МІРЯЄТЬСЯ (`gate_площі.py`).
    import fit as _ПС129, colorspace as _cs129, pipeline as _PL129, gate_площі as _GP129
    _T129 = _ПС129.тіло(168, dict(плечі=98, груди=92, талія=74, стегна=99, високе_стегно=88))
    _F129 = _cs129.features(_cs129.hx("#deb295"), _cs129.hx("#f1dbaa"), _cs129.hx("#759087"))
    _реч129 = lambda: [dict(id="a", слот="верх", hex="#8a7f74", тип="светр", верх_см=140, низ_см=95),
                       dict(id="b", слот="низ", hex="#5b4e4d", тип="штани", верх_см=100, низ_см=5),
                       dict(id="c", слот="взуття", hex="#22201e", тип="черевики", верх_см=10, низ_см=0)]
    _г129, _зв129 = O.площі_з_геометрії(_реч129(), _T129)
    тест("краї виміряні → площа рахується з геометрії тіла і несе НАЗВАНЕ походження",
         all(r.get("джерело_площі") == "геометрія" and r["площа"] > 0 for r in _г129)
         and _зв129["покриття"] == 1.0, _зв129)
    тест("частки сумуються в ОБРАЗ: площа — частка цілого, тому сума ≈ 1.0",
         abs(sum(r["площа"] for r in _г129) - 1.0) < 0.01, [r["площа"] for r in _г129])
    _г2_129, _зв2_129 = O.площі_з_геометрії(
        _реч129() + [dict(id="сумка", слот="сумка", hex="#3a3a3a")], _T129)
    тест("одна річ без виміряного краю — площі не ставляться ЖОДНІЙ, і причина названа по id: "
         "частка над підмножиною образу — та сама вигадка, лише дорожча",
         not any(r.get("джерело_площі") for r in _г2_129) and "сумка" in _зв2_129["чому"],
         _зв2_129)
    тест("`край_джерело` — реєстр, і вимір у ньому один: дефолт слота й зона зі слова "
         "площі не дають, бо перший однаковий для всього слота, а друга несе розкид",
         O.край_виміряний(dict(верх_см=1, низ_см=0, край_джерело="річ"))
         and not O.край_виміряний(dict(верх_см=1, низ_см=0, край_джерело="слово"))
         and not O.край_виміряний(dict(верх_см=1, низ_см=0, край_джерело="дефолт слота"))
         and not O.край_виміряний(dict(край_джерело="річ")), sorted(O.КРАЙ_ДЖЕРЕЛО))
    _реч3_129 = _реч129()
    _PL129.перевірити_образ(_F129, _реч3_129, тіло=_T129, нагода="робота", темп_c=18)
    тест("шов `pipeline.перевірити_образ` закритий: образ із виміряними краями доходить до "
         "суду з площею, а не з утриманням — саме цей шлях ганяє `дим`",
         all(r.get("джерело_площі") == "геометрія" for r in _реч3_129),
         [r.get("джерело_площі") for r in _реч3_129])
    _ст129 = O.review(_F129, _г129, нагода="робота", темп_c=18)["стани"]["у_приміщенні"]
    тест("пʼять правил більше не утримуються: знахідки «площа» нема, структура світлоти "
         "порахована числом",
         not any(z.get("правило") == "площа" for z in _ст129["знахідки"])
         and (_ст129["структура"] or {}).get("кроків"), _ст129["структура"])
    _ст0_129 = O.review(_F129, _реч129(), нагода="робота", темп_c=18)["стани"]["у_приміщенні"]
    _зн0_129 = ([z for z in _ст0_129["знахідки"] if z.get("правило") == "площа"] or [{}])[0]
    тест("«утримано» несе ЧИСЛО, а не лише факт: покриття входу стоїть у знахідці — "
         "0 % і 80 % доти виглядали однаково",
         _зн0_129.get("покриття_входу") == 0.0, _зн0_129.get("покриття_входу"))
    тест("`структура` при утриманні — не None: «не поміряно» і «структури нема» перестали "
         "бути одним значенням для викликача",
         isinstance(_ст0_129["структура"], dict)
         and _ст0_129["структура"].get("утримано") is True, _ст0_129["структура"])
    тест("свідок покриття існує як окремий прилад і при імпорті нічого не виконує",
         hasattr(_GP129, "образ_фіду") and hasattr(_GP129, "main")
         and isinstance(_GP129.СЛОТИ, tuple), None)

    print("130. НЕВИМІРЯНА ПЛОЩА — ОДНА ПОЛІТИКА НА ПʼЯТЬ ФУНКЦІЙ (Н-outfit-1-084)")
    # ЩО ЦЕ ЛОВИТЬ. `площа=None` — ДОКУМЕНТОВАНИЙ стан (`елементи`: «не виміряно; не
