    print("\n135. КЛАСТЕР БЕРЕ НАЙОБЕРЕЖНІШУ ТЕКСТУРУ, А ГЛАДКУ НЕ КОВТАЄ (Н-outfit-1-083)")
    # ЩО ЦЕ ЛОВИТЬ. Власний коментар `кластери` обіцяє: «якщо хоч одна річ гладка або
