    print("\n136. «МАЙЖЕ БІЛЕ» — ОДНЕ ВІКНО НА ФАЙЛ, І ВІСЬ ТЕМПЕРАТУРИ З РЕЄСТРУ (Н-outfit-1-087)")
    # ЩО ЦЕ ЛОВИТЬ. У одному файлі жили ДВА несумісні визначення «майже білого»:
    # `білі()` брала L≥85 при C<15, `МАЙЖЕ_БІЛЕ` — L≥82 при C≤28. Тобто на питання «чи
    # ця річ майже біла» файл відповідав двома різними множинами залежно від того,
    # хто питає: вужча відсікала крем, айворі й світло-жовтий — рівно те, що опис
    # класу в `МАЙЖЕ_БІЛЕ` називає ПОІМЕННО. На фікстурі `каталог_brief.xml` різниця
    # виміряна: 1604 речі проти 1746 (+142).
    # ДРУГИЙ ДУБЛЬ — ВІСЬ ТЕМПЕРАТУРИ: `білі()` мала власну пару порогів по b*
    # (тепле b>5, холодне b≤2), хоч реєстр уже несе цю вісь під `b_нейтралі`, і
    # коментар при ній прямо каже, що ці числа вже копіювались у palette.B_НЕЙТРАЛЬ.
    # Між 2 і 5 стояла ЩІЛИНА: біле з b* у ній не було ні теплим, ні холодним, тож
